// Generated by Heron Brush for Stride 4.4: the level's collision as Bullet colliders
// (the Stride.Physics package). Delete this file when the game uses other physics; the
// level file keeps the same triangles and hulls for a project of its own to read.
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Stride.Core.Mathematics;
using Stride.Engine;
using Stride.Physics;

namespace __NAMESPACE__ {
    public static class HeronBrushStridePhysics {
        // Static world geometry becomes a static triangle mesh, a mover a kinematic body of
        // convex hulls that follows its animation, and a trigger volume a trigger collider.
        // Returns the colliders by entity name.
        public static Dictionary<string,PhysicsComponent> AddColliders(HeronBrushStrideLevel.BuiltLevel level){
            var added=new Dictionary<string,PhysicsComponent>();
            foreach(var record in HeronBrushStrideLevel.Records){
                if(!record.Data.TryGetProperty("collision",out var collision))continue;
                var sensor=collision.TryGetProperty("sensor",out var flag)&&flag.GetBoolean();
                var shape=Shape(collision);
                if(shape==null)continue;
                PhysicsComponent component;
                if(collision.GetProperty("kind").GetString()=="convex"&&!sensor)
                    component=new RigidbodyComponent{RigidBodyType=RigidBodyTypes.Kinematic,ColliderShape=shape};
                else component=new StaticColliderComponent{ColliderShape=shape,IsTrigger=sensor};
                level.Entities[record.Name].Components.Add(component);
                added.Add(record.Name,component);
            }
            return added;
        }
        static ColliderShape Shape(JsonElement collision){
            if(collision.TryGetProperty("triangles",out var triangles)){
                var points=Points(triangles);
                if(points.Count<3)return null;
                return new StaticMeshColliderShape(points,Enumerable.Range(0,points.Count).ToArray());
            }
            if(!collision.TryGetProperty("hulls",out var hulls))return null;
            var shapes=hulls.EnumerateArray().Select(Points).Where(points=>points.Count>=4)
                .Select(points=>(ColliderShape)new ConvexHullColliderShape(points,Enumerable.Range(0,points.Count).Select(i=>(uint)i).ToArray(),Vector3.One)).ToList();
            if(shapes.Count==1)return shapes[0];
            if(shapes.Count==0)return null;
            var compound=new CompoundColliderShape();
            foreach(var shape in shapes)compound.AddChildShape(shape);
            return compound;
        }
        static List<Vector3> Points(JsonElement flat){
            var values=flat.EnumerateArray().Select(v=>(float)v.GetDouble()).ToArray();
            var points=new List<Vector3>(values.Length/3);
            for(var i=0;i+2<values.Length;i+=3)points.Add(new Vector3(values[i],values[i+1],values[i+2]));
            return points;
        }
    }
}
